import requests
import re
import json

url = 'https://www.youtube.com/@MrBeast/videos'
headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
resp = requests.get(url, headers=headers, timeout=15)

m = re.search(r'var ytInitialData\s*=\s*(.*?);</script>', resp.text, re.DOTALL)
data = json.loads(m.group(1))

def find_videos(d, depth=0):
    """Recursively find video-like entries"""
    if isinstance(d, dict):
        for k, v in d.items():
            if k in ('items', 'contents', 'onResponseReceivedCommands', 'continuationContents'):
                find_videos(v, depth+1)
            elif k == 'videoRenderer' or k == 'compactVideoRenderer':
                # Extract video info
                renderer = v
                vid = renderer.get('videoId', '')
                title_obj = renderer.get('title', {})
                title = ''
                if isinstance(title_obj, dict):
                    title = title_obj.get('runs', [{}])[0].get('text', '')
                pub_text = ''
                if isinstance(renderer.get('publishedTimeText'), dict):
                    pub_text = renderer['publishedTimeText'].get('runs', [{}])[0].get('text', '')
                dur = ''
                if renderer.get('lengthText'):
                    dur = renderer['lengthText'].get('simpleText', '')
                print(f'  {vid} | {title[:60]} | {pub_text} | {dur}')
            else:
                find_videos(v, depth+1)
    elif isinstance(d, list):
        for item in d:
            find_videos(item, depth)

find_videos(data)
