def explore(d, path='', max_depth=5, depth=0):
    if depth > max_depth:
        return
    if isinstance(d, dict):
        for k, v in d.items():
            new_path = f'{path}/{k}'
            if isinstance(v, dict):
                if len(v) > 20:
                    print(f'{new_path} (dict, {len(v)} keys)')
                    explore(v, new_path, max_depth, depth+1)
